  const owns = ownsMap[f.owns] || 'UNKNOWN';
  const issue = issueMap[f.issue] || null;
  const timeline = timelineMap[f.timeline] || null;
  out.push({ json: {
    fullName,
    firstName: fullName.split(' ')[0] || 'there',
    phoneDigits: digits,
    phoneE164: phoneValid ? '+1' + digits : '',
